    function processLetterboxd(imdbId) {
        const url = "https://letterboxd.com/imdb/" + imdbId;

        gmRequest({
            url: url,
            timeout: 15000,
            retries: 2,
            headers: { 'Accept-Language': 'en-US,en;q=0.9' }
        })
            .then(function (res) {
                if (res.status !== 200 || !res.responseText) return;

                let score = null;
                const ratingMatch = res.responseText.match(/\"ratingValue\":\s*([0-9.]+)/);
                if (ratingMatch) {
                    score = parseFloat(ratingMatch[1]).toFixed(1);
                } else {
                    // 兜底：JSON-LD aggregateRating
                    const ld = res.responseText.match(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/);
                    if (ld) {
                        try {
                            const parsed = JSON.parse(ld[1]);
                            const agg = parsed.aggregateRating ||
                                (Array.isArray(parsed) && parsed[0] && parsed[0].aggregateRating);
                            if (agg && agg.ratingValue) {
                                score = parseFloat(agg.ratingValue).toFixed(1);
                            }
                        } catch (e) {}
                    }
                }

                if (!score) return;
                const html = `<div class="drdm-capsule yellow-cap"><a href="${url}" target="_blank"><img src="${LBX_ICON}"><span>${score}</span></a></div>`;
                renderHeaderCapsule('header-lbx-score', html);
            })
            .catch(function (error) {
                console.warn('[Letterboxd] 加载失败：', error);
            });
    }
 
 
    // --- 其他渲染逻辑 ---
    function processOMDb(imdbId) {
        gmRequest({
            url: "https://www.omdbapi.com/?i=" + imdbId + "&apikey=thewdb",
            timeout: 12000,
            retries: 1
        })
            .then(function (res) {
                if (res.status !== 200) {
                    throw new Error('OMDb 状态码 ' + res.status);
                }

                const data = JSON.parse(res.responseText);
                if (data.Response !== "True") {
                    throw new Error('OMDb 无数据: ' + (data.Error || '未知原因'));
                }

                // 原有的 IMDb 渲染逻辑
                if (data.imdbRating && data.imdbRating !== 'N/A') {
                    renderScoreToBlock("block-imdb", "IMDb评分", data.imdbRating, data.imdbVotes, "https://www.imdb.com/title/" + imdbId + "/");
                }

                // Metacritic 联动已在 initMain 中统一触发，这里不再重复请求
            })
            .catch(function (error) {
                // OMDb 为共享 key，有每日调用上限，超限/失败时解析 IMDb 页面兜底
                console.warn('[OMDb] 加载失败，改用 IMDb 兜底：', error);
                fetchImdbRatingFallback(imdbId);
            });
    }

    // OMDb 限额用尽时，直接解析 IMDb 影片页 LD+JSON 里的评分
    function fetchImdbRatingFallback(imdbId) {
        gmRequest({
            url: "https://www.imdb.com/title/" + imdbId + "/",
            timeout: 12000,
            retries: 1,
            headers: { 'Accept-Language': 'en-US,en;q=0.9' }
        })
            .then(function (res) {
                if (res.status !== 200 || !res.responseText) return;

                // 两条正则分组顺序不同，按命中来源拆箱，避免启发式误判
                const m1 = res.responseText.match(/"aggregateRating"\s*:\s*\{[^{}]*?"ratingValue"\s*:\s*([\d.]+)[^{}]*?"ratingCount"\s*:\s*(\d+)/);
                const m2 = res.responseText.match(/"aggregateRating"\s*:\s*\{[^{}]*?"ratingCount"\s*:\s*(\d+)[^{}]*?"ratingValue"\s*:\s*([\d.]+)/);
                if (!m1 && !m2) return;

                const rating = m1 ? m1[1] : m2[2];
                const votes = Number(m1 ? m1[2] : m2[1]).toLocaleString('en-US');

                renderScoreToBlock("block-imdb", "IMDb评分", rating, votes, "https://www.imdb.com/title/" + imdbId + "/");
            })
            .catch(function (error) {
                console.warn('[IMDb 兜底] 加载失败：', error);
            });
    }
 
 
