    function processAniList(imdbId) {
        // AniList ID 已由 Wikidata 桥梁一次性带出，不再单独发 SPARQL（避免触发限流）
        getExtraIdsFromWikidata(imdbId, function (ids) {
            const anilistId = ids.anilistId;
            if (!anilistId) return;

            const query = `query ($id: Int) { Media (id: $id, type: ANIME) { id meanScore siteUrl } }`;
            gmRequest({
                method: "POST",
                url: "https://graphql.anilist.co",
                headers: { "Content-Type": "application/json" },
                data: JSON.stringify({ query: query, variables: { id: parseInt(anilistId) } }),
                timeout: 12000,
                retries: 2
            })
                .then(function (response) {
                    if (response.status !== 200 || !response.responseText) return;

                    const result = JSON.parse(response.responseText);
                    const media = result.data && result.data.Media;
                    const rating = media && media.meanScore; // 原始百分比分数 (如 85)
                    const siteUrl = media && media.siteUrl;

                    if (rating) {
                        // 保持百分比格式，拼接 %
                        const formattedScore = `${rating}%`;

                        // 直接使用脚本统一的 drdm-capsule yellow-cap 样式
                        const html = `<div class="drdm-capsule yellow-cap"><a href="${siteUrl}" target="_blank" title="点击查看 AniList 详情"><img src="${AL_ICON}"><span>${formattedScore}</span></a></div>`;

                        renderHeaderCapsule('header-anilist-score', html);
                    }
                })
                .catch(function (error) {
                    console.warn('[AniList] 加载失败：', error);
                });
        });
    }
 
    // ==================== 新增：动画评分获取与渲染模块 ====================
    // 辅助延迟函数
    const randomSleep = (max = 400, min = 200) => new Promise(resolve => setTimeout(resolve, Math.floor(Math.random() * (max - min + 1)) + min));
 
    // 1. 获取 Bangumi 评分
    function processBangumi(title) {
        const searchUrl = `https://bgm.tv/subject_search/${encodeURIComponent(title)}?cat=2`;
        
        // 获取豆瓣本页面的年份
        const yearEl = document.querySelector(".year");
        const dbYear = yearEl ? yearEl.textContent.replace(/\(|\)/g, "").trim() : null;
 
        gmRequest({
            method: "GET",
            url: searchUrl,
            timeout: 15000,
            retries: 2,
            headers: { 'Referer': 'https://bgm.tv/', 'Accept-Language': 'zh-CN,zh;q=0.9' }
        })
            .then(function (res) {
                if (res.status !== 200 || !res.responseText) return;
                try {
                    const parser = new DOMParser();
                    const doc = parser.parseFromString(res.responseText, "text/html");
                    const items = doc.querySelectorAll("#browserItemList li");
                    let matchedResult = null;
 
                    // 如果豆瓣页面有年份，优先匹配年份一致的项目
                    if (dbYear && items.length > 0) {
                        for (let i = 0; i < items.length; i++) {
                            const infoEl = items[i].querySelector(".info");
                            if (infoEl && infoEl.textContent.includes(dbYear)) {
                                matchedResult = items[i];
                                break;
                            }
                        }
                    }
 
                    // 如果按年份没有匹配到，默认取第一项
                    if (!matchedResult && items.length > 0) {
                        matchedResult = items[0];
                    }
 
                    if (matchedResult) {
                        const linkEl = matchedResult.querySelector("a.subjectCover");
                        const scoreEl = matchedResult.querySelector(".fade");
                        const countEl = matchedResult.querySelector(".tip_j");
                        
                        if (linkEl && scoreEl) {
                            const bgmUrl = "https://bgm.tv" + linkEl.getAttribute("href");
                            const score = parseFloat(scoreEl.innerText).toFixed(1);
                            const count = countEl ? countEl.innerText.replace(/[^0-9]/g, "") : "0";
                            
                            // 渲染到侧边栏，样式与 TMDB 完全保持一致
                            renderScoreToBlock("block-bangumi", "Bangumi评分", score, parseInt(count).toLocaleString(), bgmUrl);
                        }
                    }
                } catch (e) {
                    console.error("解析 Bangumi 评分失败", e);
                }
            })
            .catch(function (error) {
                console.warn('[Bangumi] 加载失败：', error);
            });
    }
 
 
    // 2. 获取 MyAnimeList (MAL) 评分
    function processMAL(title) {
        const searchUrl = `https://myanimelist.net/search/prefix.json?type=anime&keyword=${encodeURIComponent(title)}&v=1`;
        
        // 获取豆瓣本页面的年份
        const yearEl = document.querySelector(".year");
        const dbYear = yearEl ? yearEl.textContent.replace(/\(|\)/g, "").trim() : null;
 
        gmRequest({
            method: "GET",
            url: searchUrl,
            timeout: 15000,
            retries: 2,
            headers: { 'Referer': 'https://myanimelist.net/', 'Accept-Language': 'en-US,en;q=0.9' }
        })
            .then(function (res) {
                if (res.status !== 200 || !res.responseText) return;
                try {
                    const info = JSON.parse(res.responseText);
                    const items = info.categories?.[0]?.items;
                    if (items && items.length > 0) {
                        let matchedItem = null;
 
                        // 如果豆瓣页面有年份，优先匹配年份一致的项目
                        if (dbYear) {
                            for (let i = 0; i < items.length; i++) {
                                const item = items[i];
                                // MAL 返回的 aired 格式通常为 "Oct 2015" 或 "2015"
                                const airedStr = item.payload?.aired || "";
                                if (airedStr.includes(dbYear)) {
                                    matchedItem = item;
                                    break;
                                }
                            }
                        }
 
                        // 如果按年份没匹配到，则默认取第一项
                        if (!matchedItem) {
                            matchedItem = items[0];
                        }
 
                        if (matchedItem && matchedItem.url) {
                            const pageUrl = matchedItem.url;
                            // 延迟请求避免高频被ban
                            randomSleep(300, 100).then(() => {
                                gmRequest({
                                    method: "GET",
                                    url: pageUrl,
                                    timeout: 15000,
                                    retries: 2,
                                    headers: { 'Referer': 'https://myanimelist.net/', 'Accept-Language': 'en-US,en;q=0.9' }
                                })
                                    .then(function (pageRes) {
                                        if (pageRes.status !== 200 || !pageRes.responseText) return;
                                        try {
                                            const parser = new DOMParser();
                                            const doc = parser.parseFromString(pageRes.responseText, "text/html");
                                            const scoreEl = doc.querySelector(".fl-l.score");
                                            if (scoreEl) {
                                                const scoreText = scoreEl.textContent.trim();
                                                // 排除未开播无评分的情况 (N/A)
                                                if (scoreText === "N/A" || !scoreText) return;
 
                                                const score = parseFloat(scoreText).toFixed(1);
                                                const count = scoreEl.dataset.user ? scoreEl.dataset.user.replace(/users|,/g, "").trim() : "0";
                                                
                                                renderScoreToBlock("block-mal", "MAL评分", score, parseInt(count).toLocaleString(), pageUrl);
                                            }
                                        } catch (err) {
                                            console.error("解析 MAL 页面失败", err);
                                        }
                                    })
                                    .catch(function (error) {
                                        console.warn('[MAL] 影片页加载失败：', error);
                                    });
                            });
                        }
                    }
                } catch (e) {
                    console.error("获取 MAL 数据失败", e);
                }
            })
            .catch(function (error) {
                console.warn('[MAL] 搜索加载失败：', error);
            });
    }
 
 
    function renderScoreToBlock(blockId, label, score, votes, href) {
        const container = document.getElementById(blockId);
        if (!container || !score || score === "0.0" || score === "N/A") return;
        const starNum = Math.round(parseFloat(score)) * 5;
        // 窄列下用短标签（IMDb / TMDB / MyDL ...），完整名称放进 title
        const shortLabel = String(label).replace(/评分$/, '');
        const votesText = votes ? votes.toString().replace(/Ratings|Rating|Verified|人/gi, '').trim() : '';
        container.innerHTML = `<div class="drdm-rating-card__label" title="${label}">${shortLabel}</div><strong class="rating_num drdm-rating-card__num">${score}</strong><div class="drdm-rating-card__stars"><div class="bigstar bigstar${starNum}"></div></div>${votesText ? `<div class="drdm-rating-card__meta"><div class="rating_sum"><a href="${href}" target="_blank" class="rating_people" title="${label} ${votesText}"><span>${votesText}</span>评价</a></div></div>` : ''}`;
        refreshRatingGridColumns();
    }

    // 评分项 ≤2 个单列排布，>2 个改两列，控制右侧评分列高度
    function refreshRatingGridColumns() {
        const area = document.getElementById('custom-side-area');
        if (!area) return;
        const filled = Array.from(area.children).filter(child => {
            return child.innerHTML.trim() !== '';
        });
        area.classList.toggle('is-two-column', filled.length > 2);
    }

    /*
     * 紧凑布局：消除“影片信息 -> 想看/看过/剧情简介”之间的大片空白。
     *
     * 成因（2026 版豆瓣实测 DOM：双栏在 .subjectwrap 内，#interest_sect_level
     * 是其后的兄弟节点）：
     *   右栏 #interest_sectl（豆瓣评分 + 客观评分 + 各平台评分卡）被脚本撑得
     *   远高于左栏（海报 + 影片信息）；#interest_sect_level 因 clear:both 被
     *   推到两栏之下，左栏底部留下一大片空白。
     *
     * 旧方案（取消 clear + 负 margin 上移）为何无效：
     *   1. .subjectwrap 是 float:left;width:100% 的全宽浮动容器（float 自带
     *      BFC），右栏浮动列被“关”在里面，后方内容的行框不会被浮动列缩短，
     *      单纯取消 clear 毫无作用；
     *   2. 即使想看行自身没有 clear，负 margin 也会被祖先链上的 clearance
     *      规则完全吸收——只有不可见的边框盒在动，内容纹丝不动。
     *
     * 新方案（右浮动 + 解封 + 环绕，已经真实 Chrome 布局实验验证）：
     *   1. 右栏改 float:right，用 margin-right 补偿位移保持原视觉位置：
     *      左浮动会把后续内容的行框挤到右侧窄条，右浮动才会让行框从右侧
     *      收缩、自然落进左栏底部空白；
     *   2. 解封双栏容器（去浮动、去 overflow 隔离、去 clearfix 撑高），
     *      两栏浮动直接参与外层文档流；
     *   3. 取消想看行及其后方的 clear:both / clearfix 撑高 / 无子节点清除
     *      占位，内容即沿左栏底部自动环绕右栏，空白被后续内容自然填满。
     *
     * 每次执行前先还原上次修改再测量，保证定时重复执行结果一致（幂等）。
     */
    let dbCompactRestore = null;
    const DB_COMPACT_MARK = 'drdm-compact-unseal';
    /* 左栏底部与想看/看过行之间的呼吸空间（px） */
    const COMPACT_GAP = 28;

    function restoreCompactLayout() {
        if (!dbCompactRestore) return;
        dbCompactRestore.forEach(function (item) {
            if (item.type === 'class') {
                item.el.classList.remove(item.value);
            } else {
                item.el.style.setProperty(item.prop, item.value);
            }
        });
        dbCompactRestore = null;
    }

    function recordCompactStyle(el, prop) {
        dbCompactRestore.push({
            type: 'style', el: el, prop: prop,
            value: el.style.getPropertyValue(prop)
        });
    }

    /* 标记需要解除 clearfix 撑高的元素（配合注入的样式表去掉 ::after 的 clear） */
    function markCompactUnseal(el) {
        if (el.classList.contains(DB_COMPACT_MARK)) return;
        dbCompactRestore.push({ type: 'class', el: el, value: DB_COMPACT_MARK });
        el.classList.add(DB_COMPACT_MARK);
    }

    /* 注入一次样式表：被标记元素的 ::before/::after 不再清除浮动 */
    function ensureCompactStyleSheet() {
        if (document.getElementById('drdm-compact-style')) return;
        const style = document.createElement('style');
        style.id = 'drdm-compact-style';
        style.textContent = '.' + DB_COMPACT_MARK +
            '::before, .' + DB_COMPACT_MARK + '::after { clear: none !important; }';
        (document.head || document.documentElement).appendChild(style);
    }

    /* 定位“想看”链接（文本精确匹配、无元素子节点） */
    function findWishLink() {
        const links = Array.from(
            document.querySelectorAll('a, span, div, button')
        ).filter(function (element) {
            return element.childElementCount === 0 &&
                (element.textContent || '').trim() === '想看';
        });
        return links.length ? links[0] : null;
    }

    /*
     * 兜底定位“想看/看过”行：豆瓣改版后若 #interest_sect_level 不存在，
     * 从“想看”链接逐级向上，取既位于左栏、又起始于信息块下方的最外层容器。
     */
    function findWishRow(leftBottom, ratingRect) {
        const wish = findWishLink();
        if (!wish) return null;

        let target = null;
        let node = wish.parentElement;
        for (let depth = 0; depth < 10 && node && node !== document.body; depth++) {
            const rect = node.getBoundingClientRect();
            // 零高度/行内小节点只是途经祖先，跳过继续向上找行容器
            if (rect.height < 20) {
                node = node.parentElement;
                continue;
            }
            // 已走到两栏区域之上：停止上浮
            if (rect.top < leftBottom + 24) break;
            if (rect.left < ratingRect.left - 20) target = node;
            node = node.parentElement;
        }
        return target;
    }

    /*
     * 双栏容器：右栏的最近祖先，同时包含左栏（海报/信息）、但不包含想看行，
     * 且盒底与右栏底部齐平。加上这些约束才不会误伤 .article 这类更大容器
     * （误解封会把整个页面布局搞坏）。
     */
    function findColumnsWrapper(ratingCol, pic, info, below) {
        const ratingRect = ratingCol.getBoundingClientRect();
        let node = ratingCol.parentElement;
        for (let depth = 0; depth < 5 && node && node !== document.body; depth++) {
            const containsLeft = (pic && node.contains(pic)) || (info && node.contains(info));
            if (containsLeft && below && !node.contains(below) &&
                node.getBoundingClientRect().bottom <= ratingRect.bottom + 40) {
                return node;
            }
            node = node.parentElement;
        }
        return null;
    }

    /*
     * 左栏浮动列：同时包含海报与影片信息、且自身浮动的最近祖先（豆瓣经典
     * 结构即 .subject）。找不到时退回直接给海报/信息加间距。向上查找不超过
     * 双栏容器，避免误伤 .article 这类外层容器。
     */
    function findLeftColumnFloat(pic, info, bound) {
        const start = (info && info.parentElement) || (pic && pic.parentElement);
        let node = start;
        for (let depth = 0; depth < 5 && node && node !== bound && node !== document.body; depth++) {
            const holdsLeft = (!pic || node.contains(pic)) && (!info || node.contains(info));
            const floatValue = window.getComputedStyle(node).float;
            if (holdsLeft && floatValue && floatValue !== 'none') return node;
            node = node.parentElement;
        }
        return null;
    }

    /* 子树内是否存在浮动元素（判断能否安全去掉 clearfix 撑高） */
    function subtreeHasFloat(el) {
        const all = el.querySelectorAll('*');
        for (let i = 0; i < all.length; i++) {
            const value = window.getComputedStyle(all[i]).float;
            if (value && value !== 'none') return true;
        }
        return false;
    }

    /* 流内下一个元素（没有下一个兄弟时沿祖先链向上找） */
    function nextFlowElement(el) {
        if (el.nextElementSibling) return el.nextElementSibling;
        let node = el.parentElement;
        while (node && node !== document.body) {
            if (node.nextElementSibling) return node.nextElementSibling;
            node = node.parentElement;
        }
        return null;
    }

    /* 取消子树中“无元素子节点”的清除占位（如 <div class="clear">） */
    function neutralizeChildlessClears(root) {
        const all = root.querySelectorAll('*');
        for (let i = 0; i < all.length; i++) {
            const el = all[i];
            if (el.childElementCount !== 0) continue;
            const value = window.getComputedStyle(el).clear;
            if (value && value !== 'none') {
                recordCompactStyle(el, 'clear');
                el.style.setProperty('clear', 'none', 'important');
            }
        }
    }

    function compactSubjectLayout() {
        const ratingCol = document.getElementById('interest_sectl');
        const pic = document.getElementById('mainpic');
        const info = document.getElementById('info');
        if (!ratingCol || (!pic && !info)) return;

        // 先还原再测量，保证定时重复执行结果一致（幂等）
        restoreCompactLayout();
        dbCompactRestore = [];

        const picRect = pic ? pic.getBoundingClientRect() : null;
        const infoRect = info ? info.getBoundingClientRect() : null;
        if (!picRect && !infoRect) return;

        // 左栏内容底部：海报与影片信息中较低的底部
        const leftBottom = Math.max(
            picRect ? picRect.bottom : 0,
            infoRect ? infoRect.bottom : 0
        );

        const ratingRect = ratingCol.getBoundingClientRect();

        /*
         * 仅处理“双栏且右栏更高”的页面：
         * 右栏起始于左栏底部之上（两栏并排），并延伸到底部之下（才是空白成因）。
         * 窄屏堆叠布局（右栏在左栏下方）不处理。
         */
        if (ratingRect.top > leftBottom - 24) return;
        if (ratingRect.bottom < leftBottom + 24) return;

        // 右栏必须是左浮动（豆瓣经典双栏），否则本方案不适用
        const ratingFloat = window.getComputedStyle(ratingCol).float;
        if (ratingFloat !== 'left') {
            console.info('[紧凑布局] 右栏非左浮动（' + ratingFloat + '），跳过');
            return;
        }

        // 想看/看过行：优先用稳定 id，兜底按“想看”链接定位
        let below = document.getElementById('interest_sect_level');
        if (below && (ratingCol.contains(below) || below.contains(ratingCol))) below = null;
        if (!below) below = findWishRow(leftBottom, ratingRect);
        if (!below) {
            console.info('[紧凑布局] 未找到想看/看过行');
            return;
        }

        ensureCompactStyleSheet();

        /*
         * 解封双栏容器：去掉浮动与 overflow 隔离（BFC），两栏浮动才能参与
         * 外层流；clearfix 的 ::after 撑高也要解除，否则容器盒底仍与右栏
         * 齐平，后续内容依旧被压在下方。
         */
        const wrapper = findColumnsWrapper(ratingCol, pic, info, below);
        if (wrapper) {
            const wrapStyle = window.getComputedStyle(wrapper);
            const display = wrapStyle.display;
            if (display === 'flex' || display === 'inline-flex' || display === 'grid' ||
                display === 'inline-grid' || display === 'flow-root' ||
                display === 'inline-block' || display === 'table-cell') {
                console.info('[紧凑布局] 双栏容器 display:' + display + '，无法安全解封，跳过');
                return;
            }
            if (wrapStyle.float && wrapStyle.float !== 'none') {
                recordCompactStyle(wrapper, 'float');
                wrapper.style.setProperty('float', 'none', 'important');
            }
            if (wrapStyle.overflow && wrapStyle.overflow !== 'visible') {
                recordCompactStyle(wrapper, 'overflow');
                wrapper.style.setProperty('overflow', 'visible', 'important');
            }
            markCompactUnseal(wrapper);
            // clearfix 之外仍有撑高来源、且子节点全是浮动时，压掉容器高度
            if (wrapper.getBoundingClientRect().height > 4) {
                const kids = wrapper.children;
                let allFloat = kids.length > 0;
                for (let i = 0; i < kids.length; i++) {
                    const floatValue = window.getComputedStyle(kids[i]).float;
                    if (!floatValue || floatValue === 'none') { allFloat = false; break; }
                }
                if (allFloat) {
                    recordCompactStyle(wrapper, 'height');
                    wrapper.style.setProperty('height', '0', 'important');
                    console.info('[紧凑布局] 双栏容器仍被撑高，已强制 height:0');
                } else {
                    console.info('[紧凑布局] 双栏容器仍被撑高但含非浮动子节点，跳过 height:0');
                }
            }
        } else {
            console.info('[紧凑布局] 未找到可解封的双栏容器，仅取消清除');
        }

        /*
         * 右栏改右浮动：左浮动会把后续内容的行框挤到右侧窄条，右浮动才会让
         * 行框从右侧收缩、落进左栏底部空白；margin-right 补偿位移保持原位。
         */
        const container = wrapper || ratingCol.parentElement;
        const containerStyle = window.getComputedStyle(container);
        const containerRight = container.getBoundingClientRect().right -
            (parseFloat(containerStyle.paddingRight) || 0) -
            (parseFloat(containerStyle.borderRightWidth) || 0);
        const marginRight = Math.max(0, Math.round(containerRight - ratingRect.right));
        recordCompactStyle(ratingCol, 'float');
        recordCompactStyle(ratingCol, 'margin-right');
        ratingCol.style.setProperty('float', 'right', 'important');
        ratingCol.style.setProperty('margin-right', marginRight + 'px', 'important');

        /*
         * 想看行到外层容器之间：取消 clear:both 与 overflow 隔离，
         * 否则行框仍被推到两栏之下，或被 BFC 挡住无法环绕。
         */
        const chainEnd = wrapper ? wrapper.parentElement : container;
        let node = below.parentElement;
        for (let depth = 0; depth < 6 && node && node !== chainEnd && node !== document.body; depth++) {
            const style = window.getComputedStyle(node);
            if (style.clear && style.clear !== 'none') {
                recordCompactStyle(node, 'clear');
                node.style.setProperty('clear', 'none', 'important');
            }
            if (style.overflow && style.overflow !== 'visible') {
                recordCompactStyle(node, 'overflow');
                node.style.setProperty('overflow', 'visible', 'important');
            }
            markCompactUnseal(node);
            node = node.parentElement;
        }
        // 外层容器自身：解除 clearfix 撑高，后续内容才能继续上移
        if (chainEnd && chainEnd !== document.body) markCompactUnseal(chainEnd);

        // 想看行自身：取消 clear、overflow 隔离与 clearfix 撑高
        const belowStyle = window.getComputedStyle(below);
        if (belowStyle.clear && belowStyle.clear !== 'none') {
            recordCompactStyle(below, 'clear');
            below.style.setProperty('clear', 'none', 'important');
        }
        if (belowStyle.overflow && belowStyle.overflow !== 'visible') {
            recordCompactStyle(below, 'overflow');
            below.style.setProperty('overflow', 'visible', 'important');
        }
        markCompactUnseal(below);

        /*
         * 想看行之后的流内元素：若仍在右栏覆盖的纵向范围内，取消其 clear
         * 阻挡与清除占位，让内容持续上移、环绕右栏排布。
         */
        let flow = nextFlowElement(below);
        for (let i = 0; i < 24 && flow && flow !== document.body; i++) {
            if (flow.getBoundingClientRect().top > ratingRect.bottom + 24) break;
            const style = window.getComputedStyle(flow);
            if (style.clear && style.clear !== 'none') {
                recordCompactStyle(flow, 'clear');
                flow.style.setProperty('clear', 'none', 'important');
            }
            if (!subtreeHasFloat(flow)) {
                markCompactUnseal(flow);
                neutralizeChildlessClears(flow);
            }
            flow = nextFlowElement(flow);
        }

        /*
         * 左栏底部与想看行之间留一点呼吸空间：把左栏浮动列的外边缘向下
         * 扩展，行框被浮动推得更低。用 margin-bottom（在边框盒之外，左栏
         * 即使有背景色也不会出现色带）；间距固定，自适应各页面左栏高度。
         */
        const leftFloat = findLeftColumnFloat(pic, info, wrapper || container);
        const gapTargets = leftFloat ? [leftFloat] : [pic, info].filter(Boolean);
        for (let i = 0; i < gapTargets.length; i++) {
            const target = gapTargets[i];
            if (!target || target === ratingCol) continue;
            recordCompactStyle(target, 'margin-bottom');
            target.style.setProperty('margin-bottom', COMPACT_GAP + 'px', 'important');
        }

        // 验证：想看行内容是否已落入左栏空白
        const wish = findWishLink();
        const wishTop = wish ? wish.getBoundingClientRect().top : below.getBoundingClientRect().top;
        console.info(
            '[紧凑布局] 右栏改右浮动(margin-right:' + marginRight + 'px)' +
            (wrapper ? '，已解封双栏容器' : '') +
            '；空白 ' + Math.round(ratingRect.bottom - leftBottom) + 'px' +
            '；想看行内容位置 ' + Math.round(wishTop) +
            '（左栏底部 ' + Math.round(leftBottom) + ' + 间隙 ' + COMPACT_GAP + 'px）'
        );
        if (wishTop > leftBottom + 24) {
            console.info('[紧凑布局] 警告：内容仍未进入空白区，页面结构可能不符合预期');
        }
    }

    // 各平台评分异步返回时间不一，兜底刷新几次网格列数
    refreshRatingGridColumns();
    setTimeout(refreshRatingGridColumns, 1500);
    setTimeout(refreshRatingGridColumns, 5000);

    initRankings();
    initMain();
 
    (function addViewOriginalLogic() {
        const mainPic = document.querySelector('#mainpic');
        if (!mainPic) return;
        const img = mainPic.querySelector('img');
        if (img) {
            const rawUrl = img.src.replace(/photo\/[sl](_ratio_poster|pic)\/public\/(p\d+).+$/, "photo/l/public/$2.jpg");
            const btn = document.createElement('a');
            btn.className = 'view-original-btn';
            btn.href = rawUrl;
            btn.target = '_blank';
            btn.innerText = '查看原图';
            mainPic.appendChild(btn);
        }
    })();

        (function () {
        'use strict';

        const info = document.querySelector('#info');

        if (!info) {
            return;
        }

        // 查找“IMDb:”对应的标签
        const imdbLabel = Array.from(info.querySelectorAll('.pl')).find((element) => {
            return element.textContent.trim().toLowerCase() === 'imdb:';
        });

        if (!imdbLabel) {
            return;
        }

        /*
        * IMDb 编号是“IMDb:”标签后面的文本节点，例如：
        *
        * <span class="pl">IMDb:</span> tt0103064<br>
        */
        let node = imdbLabel.nextSibling;

        while (node && node.nodeName !== 'BR') {
            if (node.nodeType === Node.TEXT_NODE) {
                const match = node.textContent.match(/\b(tt\d+)\b/i);

                if (match) {
                    const imdbId = match[1].toLowerCase();
                    const beforeText = node.textContent.slice(0, match.index);
                    const afterText = node.textContent.slice(
                        match.index + match[0].length
                    );

                    const link = document.createElement('a');

                    link.href = `https://www.imdb.com/title/${imdbId}/`;
                    link.textContent = imdbId;
                    link.target = '_blank';
                    link.rel = 'noopener noreferrer';
                    link.title = `在 IMDb 查看 ${imdbId}`;

                    Object.assign(link.style, {
                        display: 'inline-block',
                        padding: '1px 6px',
                        backgroundColor: '#f5a623',
                        color: '#ffffff',
                        borderRadius: '3px',
                        textDecoration: 'none',
                        fontWeight: 'bold',
                        lineHeight: '1.5'
                    });

                    // 鼠标悬停效果
                    link.addEventListener('mouseenter', () => {
                        link.style.backgroundColor = '#e08b00';
                    });

                    link.addEventListener('mouseleave', () => {
                        link.style.backgroundColor = '#f5a623';
                    });

                    const fragment = document.createDocumentFragment();

                    fragment.append(
                        document.createTextNode(beforeText),
                        link,
                        document.createTextNode(afterText)
                    );

                    node.replaceWith(fragment);

                    // 等待侧栏 #block-tmdb 内的 TMDB 链接异步加载完成
                    const addTmdbBadge = () => {
                        // 避免重复添加
                        if (link.parentNode?.querySelector('.tmdb-id-badge')) {
                            return true;
                        }

                        const tmdbUrl = document.querySelector('#block-tmdb a')?.href || '';
                        const tmdbMatch = tmdbUrl.match(/\/(?:movie|tv)\/(\d+)/i);

                        if (!tmdbMatch) {
                            return false;
                        }

                        const tmdbId = tmdbMatch[1];

                        // “TMDB:”作为普通文本显示
                        const tmdbLabel = document.createElement('span');

                        // 使用豆瓣原有的 .pl 样式，与 “IMDb:” 的文字颜色保持一致
                        tmdbLabel.className = imdbLabel.className;
                        tmdbLabel.textContent = ' TMDB: ';
                        tmdbLabel.style.marginLeft = '6px';

                        // 只有 TMDB ID 做成橙色链接徽标
                        const tmdbLink = document.createElement('a');

                        tmdbLink.className = 'tmdb-id-badge';
                        tmdbLink.href = tmdbUrl;
                        tmdbLink.textContent = tmdbId;
                        tmdbLink.target = '_blank';
                        tmdbLink.rel = 'noopener noreferrer';
                        tmdbLink.title = `在 TMDB 查看 ${tmdbId}`;

                        Object.assign(tmdbLink.style, {
                            display: 'inline-block',
                            padding: '1px 6px',
                            backgroundColor: '#f5a623',
                            color: '#ffffff',
                            borderRadius: '3px',
                            textDecoration: 'none',
                            fontWeight: 'bold',
                            lineHeight: '1.5'
                        });

                        tmdbLink.addEventListener('mouseenter', () => {
                            tmdbLink.style.backgroundColor = '#e08b00';
                        });

                        tmdbLink.addEventListener('mouseleave', () => {
                            tmdbLink.style.backgroundColor = '#f5a623';
                        });

                        // 在 IMDb ID 后依次插入普通 TMDB 标签和橙色 TMDB ID
                        link.insertAdjacentElement('afterend', tmdbLabel);
                        tmdbLabel.insertAdjacentElement('afterend', tmdbLink);

                        return true;
                    };

                    if (!addTmdbBadge()) {
                        const timer = setInterval(() => {
                            if (addTmdbBadge()) {
                                clearInterval(timer);
                            }
                        }, 300);

                        // 最多等待 15 秒，避免页面上永久保留定时器
                        setTimeout(() => clearInterval(timer), 15000);
                    }

                    return;
                }
            }

            node = node.nextSibling;
        }
    })();
 
    // =====================================================================
    // --- 复制简介模块（完整版格式增强）---
    // ① ◎译　　名 / ◎片　　名（拆分中英文标题）
    // ② 完整演职员表：导演 / 演员 / 编剧 / 音乐 / 摄影 / 美术 / 服装 / 动作特技 …
    // ③ 人名中文与外文名以 " / " 分隔，演员附角色名（仅保留"配/饰"角色，去掉"配音 Voice"前缀）
    // ④ ◎获奖情况（抓取豆瓣奖项页，位于简介之后）
    // =====================================================================
 
